#!/usr/bin/env bash
# M0-E benchmark matrix (v3). Usage: bash bench.sh gpu|cpu|vram   (appends to results/bench.jsonl)
# Shared dev box: GPU runs wait <= 3 min for CPU load < 40 %, CPU runs wait <= 10 min for < 25 %;
# the load at start is logged ("busy:NN" = ran anyway). Do not edit this file while it runs.
set -u
B=./target/release/gpu-tier-spike.exe
load() { powershell -NoProfile -c "(Get-CimInstance Win32_Processor | Measure-Object LoadPercentage -Average).Average"; }
wait_idle() { # max_load tries(10 s each)
  for i in $(seq 1 $2); do
    a=$(load); sleep 3; b=$(load)
    if [ "${a%.*}" -lt $1 ] && [ "${b%.*}" -lt $1 ]; then echo "$b"; return; fi
    sleep 7
  done
  echo "busy:$(load)"
}
run() { # reps model_dir file ep n batches
  local reps=$1; shift
  if [ "$3" = dml ]; then W="40 18"; else W="25 60"; fi
  for r in $(seq 1 $reps); do
    l=$(wait_idle $W); echo ">> rep=$r cpu_load_at_start=$l $*" >&2
    SR_CPU_LOAD="$l" "$B" bench "$@" >/dev/null || echo "FAILED: $*" >&2
  done
}
case "${1:-}" in
gpu) # 1024 chunks x 512 tokens; warm-up covers all batch sizes (VRAM here = batch-128 arena)
  for m in "bge-small model_fp16.onnx" "bge-small model_int8.onnx" "bge-small-q model_optimized.onnx" \
           "bge-base model_fp16.onnx" "arctic-m model_fp16.onnx" "arctic-m model.onnx" "arctic-m model_int8.onnx" "nomic model_fp16.onnx" \
           "bge-large model_fp16.onnx" "mxbai model_fp16.onnx" "arctic-l model_fp16.onnx" "gte-large model_fp16.onnx"; do
    set -- $m; run 1 models/$1 $2 dml 1024 16,32,64,128
  done ;;
cpu)
  for m in "bge-small model_int8.onnx" "bge-small-q model_optimized.onnx" "bge-small model.onnx" "bge-base model_int8.onnx" "arctic-m model_int8.onnx" "nomic model_int8.onnx"; do
    set -- $m; run 2 models/$1 $2 cpu 256 8,16,32
  done
  for m in "bge-large model_int8.onnx" "mxbai model_int8.onnx" "arctic-l model_int8.onnx" "gte-large model_int8.onnx"; do
    set -- $m; run 1 models/$1 $2 cpu 128 8,16
  done
  run 1 models/arctic-m model.onnx cpu 64 16
  run 1 models/arctic-m model_fp16.onnx cpu 64 16
  run 1 models/arctic-l model_fp16.onnx cpu 64 16
  run 1 models/gte-large model_fp16.onnx cpu 64 16 ;;
vram) # one batch size per process => arena peak for that batch size
  for m in "bge-small model_int8.onnx" "bge-small model.onnx" "arctic-m model_fp16.onnx" "arctic-l model_fp16.onnx" "gte-large model_fp16.onnx"; do
    for b in 16 32 64; do set -- $m; run 1 models/$1 $2 dml 256 $b; done
  done ;;
*) echo "usage: bench.sh gpu|cpu|vram" >&2; exit 2 ;;
esac
echo "DONE phase" >&2
